/**
 * Catalogue data.
 *
 * src/data/catalogue.json is generated by scripts/build-catalogue.mjs from the
 * photographs in public/images/catalogue. Nothing here is hand-entered: one
 * image becomes one product, and the only optional extra data comes from
 * products.csv.
 */

import raw from "@/data/catalogue.json";
import { computeBreakup, type RateMap } from "./pricing";

export interface CatalogueProduct {
  code: string;
  name: string;
  category: string;
  categoryLabel: string;
  metal: "GOLD" | "SILVER";
  purity: string;
  weightG: number | null;
  makingPercent: number;
  hasWeight: boolean;
  subtype: string | null;
  occasion: string | null;
  status: string;
  featured: boolean;
  image: string;
  thumb: string;
  blur: string;
  /** Per-piece overrides — see CATALOGUE_FLAGS. Off unless the shop sets them. */
  hallmark?: boolean;
  scarcity?: number;
}

interface CatalogueFile {
  generatedAt: string;
  count: number;
  products: CatalogueProduct[];
}

const file = raw as CatalogueFile;

export const catalogueProducts: CatalogueProduct[] = file.products.filter(
  (product) => product.status !== "hidden",
);

export const catalogueGeneratedAt = file.generatedAt;

export const CATEGORY_LABELS: Record<string, string> = {
  rings: "Gold Rings",
  diamond: "Diamond Rings",
  earrings: "Earrings",
  necklaces: "Necklaces",
  pendants: "Pendants",
  bangles: "Bangles",
  mangalsutra: "Mangalsutra",
  bracelets: "Bracelets",
  "nose-pins": "Nose Pins",
  silver: "Silver",
  "silver-coins": "Silver Coins & Idols",
  mens: "Men's",
  kids: "Kids",
};

export const CATEGORY_ORDER = [
  "rings",
  "diamond",
  "earrings",
  "necklaces",
  "pendants",
  "bangles",
  "mangalsutra",
  "bracelets",
  "nose-pins",
  "silver",
  "silver-coins",
  "mens",
  "kids",
] as const;

export interface CategoryCount {
  slug: string;
  label: string;
  count: number;
}

/** Categories that actually exist in the folder, with real counts. */
export function categoryCounts(products: CatalogueProduct[] = catalogueProducts): CategoryCount[] {
  const map = new Map<string, CategoryCount>();
  for (const product of products) {
    const existing = map.get(product.category);
    if (existing) existing.count += 1;
    else map.set(product.category, { slug: product.category, label: product.categoryLabel, count: 1 });
  }
  return [...map.values()].sort((a, b) => {
    const ai = CATEGORY_ORDER.indexOf(a.slug as (typeof CATEGORY_ORDER)[number]);
    const bi = CATEGORY_ORDER.indexOf(b.slug as (typeof CATEGORY_ORDER)[number]);
    return (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi) || a.label.localeCompare(b.label);
  });
}

export function purities(products: CatalogueProduct[] = catalogueProducts): string[] {
  return [...new Set(products.map((product) => product.purity))].sort((a, b) => {
    const order = ["24K", "22K", "18K", "999", "925"];
    return order.indexOf(a) - order.indexOf(b);
  });
}

export function occasions(products: CatalogueProduct[] = catalogueProducts): string[] {
  return [...new Set(products.map((product) => product.occasion).filter((value): value is string => Boolean(value)))].sort();
}

export function weightBounds(products: CatalogueProduct[]): { min: number; max: number } | null {
  const weights = products.map((product) => product.weightG).filter((value): value is number => typeof value === "number");
  if (!weights.length) return null;
  return { min: Math.floor(Math.min(...weights)), max: Math.ceil(Math.max(...weights)) };
}

/**
 * Approximate counter price: weight × live rate for the purity + making, then
 * GST. Returns null when the sheet has no weight — the UI then asks for an
 * enquiry instead of showing a made-up number.
 */
export function approxPrice(product: CatalogueProduct, rates: RateMap): number | null {
  if (!product.hasWeight || !product.weightG) return null;
  const breakup = computeBreakup(
    {
      metal: product.metal,
      purity: product.purity,
      weight: product.weightG,
      gemstoneValue: 0,
      makingPct: product.makingPercent,
    },
    rates,
  );
  return breakup.total > 0 ? breakup.total : null;
}

export function enquiryMessage(product: CatalogueProduct, price: number | null): string {
  const pricePart = price ? ` The approximate price shown is ₹${price.toLocaleString("en-IN")}.` : "";
  return `Namaste JMD Gems & Jewellery. I would like to enquire about ${product.name} (code ${product.code}).${pricePart} Please share the weight, making charges and availability.`;
}
